# Code generated by Claude
"""
The demo video: one real, unstaged run of the moved layout (the beaker and the hotplate 15 cm toward smaller x, as in stance_select_moved_test), the whole pipeline from the typed instruction to the arm back
at the zombie pose, recorded as an MP4 (H.264) of the standard viewer layout (the follow camera, the status panel upper left, the camera tiles along the bottom).

    python experiments/demo_video.py [--instruction "put the beaker on the hotplate"] [--hz 30] [--name demo_moved]

How it is made: (1) the episode runs with the planner reading only the stored reply (LLM mode cache_only, no API call), the simulator's own checks deciding (checker "oracle"), and the state recorded
(src/run_record). If the outcome is not SUCCESS the script stops and says so: no video, no retry, nothing tuned. (2) The recording is replayed in replay_run's "viewer" mode, the existing way to
render the viewer's picture: one frame every 1/hz seconds of SIMULATED time (the physics step counter, never the wall clock), so a slow or frozen VM cannot show up as a stall; the replay verifies
the states bit-identical, so the video shows exactly the run that was checked. (3) The frames go to an H.264 encoder (the OpenCV build here has none, so the ffmpeg of the imageio-ffmpeg package is
used through a pipe; replay's cv2 writer is replaced for this script only). The file is written under a temporary name and renamed when complete (CLAUDE.md rule 4).

Output (not in Git: data/ is ignored): data/videos/<name>_<time>.mp4, <name>_<time>.json (the facts of the run), <name>_<time>_handoff.png (replay's picture at the handoff). The work folder with the
recording is deleted when the video is complete.
"""

import argparse
import json
import os
import shutil
import subprocess
import sys
import time
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import cv2  # noqa: E402
import imageio_ffmpeg  # noqa: E402

import src.replay as replay_mod  # noqa: E402
from src.episode_runner import run_episode  # noqa: E402
from src.llm_gemini import GeminiCaller  # noqa: E402
from src.mpvi_pipeline import make_pipeline_task  # noqa: E402
from src.mpvi_planner import make_llm_planner  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import LLM_CFG, TASK_CFG  # noqa: E402

SHIFT_X = -0.15
MOVED = {**TASK_CFG, "beaker_xy": (TASK_CFG["beaker_xy"][0] + SHIFT_X, TASK_CFG["beaker_xy"][1]), "hotplate_xy": (TASK_CFG["hotplate_xy"][0] + SHIFT_X, TASK_CFG["hotplate_xy"][1])}


class X264Writer:
    """Writes BGR frames (numpy arrays, like cv2.VideoWriter.write) to an H.264 MP4 through a pipe to ffmpeg."""

    def __init__(self, path, fps, size, log_path):
        w, h = size
        cmd = [imageio_ffmpeg.get_ffmpeg_exe(), "-y", "-loglevel", "warning", "-f", "rawvideo", "-pix_fmt", "bgr24", "-s", f"{w}x{h}", "-r", str(fps), "-i", "-",
               "-c:v", "libx264", "-preset", "medium", "-crf", "18", "-pix_fmt", "yuv420p", "-movflags", "+faststart", "-f", "mp4", str(path)]
        self.log = open(log_path, "w")
        self.proc = subprocess.Popen(cmd, stdin=subprocess.PIPE, stderr=self.log)

    def write(self, frame):
        self.proc.stdin.write(frame.tobytes())

    def release(self):
        self.proc.stdin.close()
        rc = self.proc.wait()
        self.log.close()
        if rc != 0:
            raise RuntimeError(f"ffmpeg exited with {rc}")


def main(args):
    stamp = time.strftime("%Y%m%d_%H%M%S")
    stem = f"{args.name}_{stamp}"
    vids = PROJECT_ROOT / "data" / "videos"
    work = vids / f"work_{stamp}"
    work.mkdir(parents=True, exist_ok=True)
    facts = {"instruction": args.instruction, "layout": {"beaker_xy": MOVED["beaker_xy"], "hotplate_xy": MOVED["hotplate_xy"]}, "llm_mode": "cache_only", "checker": "oracle", "hz": args.hz, "model": LLM_CFG["model"]}
    caller = GeminiCaller(mode="cache_only")
    plan = make_llm_planner(caller.bind("plan", LLM_CFG["planner_prompt_version"]))(args.instruction)
    print("the plan:\n" + "\n".join(f"  {i}. [{s['type']}] {s['description']}" for i, s in enumerate(plan["segments"])), flush=True)
    sim = load_task(MOVED, cameras=True)
    task = make_pipeline_task(plan, task_cfg=MOVED, stop_on_disagreement=True, checker="oracle")
    t0 = time.perf_counter()
    s = run_episode(task, sim.model, sim.data, out_dir=work / "episode", record_dir=work / "recording")
    state = task["pipeline"]["orchestrator"]["state"]
    ok_success, _ = task["check_success"](sim.model, sim.data)
    facts.update(outcome=s["outcome"], plan_failure=state["failure"], status=state["status"], beaker_on_hotplate=bool(ok_success), episode_wall_s=time.perf_counter() - t0)
    print(f"outcome {s['outcome']}; plan failure {state['failure']}; status {state['status']}; beaker on the hotplate {ok_success}", flush=True)
    if s["outcome"] != "SUCCESS" or not all(x == "done" for x in state["status"]) or not ok_success:
        (vids / f"{stem}_FAILED.json").write_text(json.dumps(facts, indent=1, default=str))
        print(f"FAILED: no video made, nothing retried; facts in {vids / (stem + '_FAILED.json')}; the work folder {work} is kept", flush=True)
        return 1
    del sim, task
    replay_mod.open_video = lambda path, fps, size, codec="mp4v", quality=None: X264Writer(path, fps, size, work / "ffmpeg.log")
    r = replay_mod.replay_run(work / "recording", out_dir=work / "video", video="viewer", hz=float(args.hz), name=stem, quiet=True)
    facts.update(replay_ok=bool(r["ok"]), replay_ticks=r.get("n_ticks_recorded"), mismatch=r.get("mismatch"), frames=r.get("frames_rendered"))
    print(f"replay ok {r['ok']} ({r.get("n_ticks_recorded")} ticks, mismatch {r.get("mismatch")}); frames {r.get("frames_rendered")}", flush=True)
    made = work / "video" / f"{stem}.mp4"
    if not r["ok"] or not made.exists():
        (vids / f"{stem}_FAILED.json").write_text(json.dumps(facts, indent=1, default=str))
        print("the replay did not reproduce the run or wrote no file: no video kept", flush=True)
        return 1
    cap = cv2.VideoCapture(str(made))
    n = int(cap.get(cv2.CAP_PROP_FRAME_COUNT))
    cap.release()
    facts.update(video=str(vids / f"{stem}.mp4"), size_bytes=made.stat().st_size, frame_count_in_file=n, length_s=n / args.hz, resolution=[1920, 1080], codec="H.264 (libx264, crf 18, yuv420p)")
    shutil.move(str(made), str(vids / f"{stem}.mp4"))
    still = work / "video" / f"{stem}_handoff.png"
    if still.exists():
        shutil.move(str(still), str(vids / f"{stem}_handoff.png"))
    tmp = vids / f"{stem}.json.tmp"
    tmp.write_text(json.dumps(facts, indent=1, default=str))
    tmp.replace(vids / f"{stem}.json")
    shutil.rmtree(work, ignore_errors=True)
    print(f"DONE: {vids / (stem + '.mp4')}  {facts['length_s']:.1f} s, {facts['size_bytes'] / 1e6:.1f} MB", flush=True)
    return 0


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[1])
    ap.add_argument("--instruction", default="put the beaker on the hotplate")
    ap.add_argument("--hz", type=int, default=30, help="video frames per simulated second (a whole divisor of the physics rate)")
    ap.add_argument("--name", default="demo_moved")
    sys.exit(main(ap.parse_args()))
